#pragma once
namespace merchant {
inline void workspaces(crow::SimpleApp &app){
    CROW_ROUTE(app,"/api/workspaces")([](const crow::request &r){return handle([&]{Db d(path);auto current=owner(d,r);auto user=principal(d,r);Stmt s(d,"SELECT o.id,s.name,m.role FROM workspace_members m JOIN owners o ON o.id=m.workspace_owner JOIN stalls s ON s.owner_id=o.id WHERE m.principal_id=? ORDER BY s.name,o.id");s.bind(1,user);Json out;out["current"]=current;out["workspaces"]=Json::list();int i=0;while(s.row()){out["workspaces"][i]["id"]=s.num(0);out["workspaces"][i]["name"]=s.str(1);out["workspaces"][i++]["role"]=s.str(2);}return json(200,std::move(out));});});
    CROW_ROUTE(app,"/api/workspaces/switch").methods("POST"_method)([](const crow::request &r){return handle([&]{Db d(path);owner(d,r);auto user=principal(d,r);auto j=body(r);auto target=integer(j,"workspace_id",1,1000000000);Stmt member(d,"SELECT 1 FROM workspace_members WHERE principal_id=? AND workspace_owner=?");member.bind(1,user).bind(2,target);require(member.row(),403,"Workspace access denied");Stmt update(d,"UPDATE sessions SET owner_id=? WHERE hash=? AND principal_id=?");update.bind(1,target).bind(2,digest(r.get_header_value("Authorization").substr(7))).bind(3,user).row();Json out;out["switched"]=true;return json(200,std::move(out));});});
    CROW_ROUTE(app,"/api/branches").methods("POST"_method)([](const crow::request &r){return handle([&]{Db d(path);auto current=owner(d,r);auto user=principal(d,r);auto j=body(r);auto name=text(j,"name",120);Transaction tx(d);
        Stmt count(d,"SELECT COUNT(*) FROM owners WHERE business_root=?");count.bind(1,user);count.row();require(count.num(0)<20,409,"Maximum twenty additional branches");auto random=token();Stmt insert(d,"INSERT INTO owners(email,salt,password,verified,business_root,is_branch) VALUES(?,?,?,1,?,1)");insert.bind(1,"branch-"+random+"@internal.invalid").bind(2,token()).bind(3,token()).bind(4,user).row();auto branch=sqlite3_last_insert_rowid(d.p);Stmt st(d,"INSERT INTO stalls(owner_id,name) VALUES(?,?)");st.bind(1,branch).bind(2,name).row();Stmt member(d,"INSERT INTO workspace_members VALUES(?,?,'OWNER')");member.bind(1,user).bind(2,branch).row();audit(d,"BRANCH_CREATED",std::to_string(branch),std::to_string(user),"from="+std::to_string(current));tx.commit();Json out;out["workspace_id"]=branch;return json(201,std::move(out));});});
    CROW_ROUTE(app,"/api/workers").methods("GET"_method,"POST"_method)([](const crow::request &r){return handle([&]{Db d(path);auto workspace=owner(d,r);auto user=principal(d,r);Stmt admin(d,"SELECT role FROM workspace_members WHERE principal_id=? AND workspace_owner=?");admin.bind(1,user).bind(2,workspace);require(admin.row()&&admin.str(0)=="OWNER",403,"Only the business owner manages workers");
        if(r.method==crow::HTTPMethod::Post){auto j=body(r);auto email=emailAddress(text(j,"email",200)),role=text(j,"role",20);require(role=="MANAGER"||role=="FULFILMENT"||role=="ACCOUNTANT"||role=="REVOKED",400,"Invalid worker role");Stmt account(d,"SELECT id FROM owners WHERE email=? AND verified=1 AND is_branch=0");account.bind(1,email);require(account.row(),404,"Worker must register and verify their own email first");auto worker=account.num(0);require(worker!=user&&worker!=workspace,409,"Cannot change the owner role");Stmt old(d,"SELECT role FROM workspace_members WHERE principal_id=? AND workspace_owner=?");old.bind(1,worker).bind(2,workspace);if(old.row())require(old.str(0)!="OWNER",403,"Owner cannot be reassigned");Transaction tx(d);
            if(role=="REVOKED"){Stmt remove(d,"DELETE FROM workspace_members WHERE principal_id=? AND workspace_owner=?");remove.bind(1,worker).bind(2,workspace).row();}else{Stmt save(d,"INSERT INTO workspace_members VALUES(?,?,?) ON CONFLICT(principal_id,workspace_owner) DO UPDATE SET role=excluded.role");save.bind(1,worker).bind(2,workspace).bind(3,role).row();}audit(d,"WORKER_ROLE",std::to_string(workspace),std::to_string(user),std::to_string(worker)+":"+role);tx.commit();}
        Stmt s(d,"SELECT o.email,m.role FROM workspace_members m JOIN owners o ON o.id=m.principal_id WHERE m.workspace_owner=? ORDER BY o.email");s.bind(1,workspace);Json out;out["workers"]=Json::list();int i=0;while(s.row()){out["workers"][i]["email"]=s.str(0);out["workers"][i++]["role"]=s.str(1);}return json(200,std::move(out));
    });});
}
}
